import re

def evaluate(expr: str) -> float:
    tokens = re.findall(r'\d+\.\d+|\d+\.|\.\d+|\d+|[()+\-*/]|\S', expr)
    tokens = [t for t in tokens if not t.isspace()]
    # remove spaces already filtered since findall with \S
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_unary()
            if op == '*':
                val = val * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
        return val

    def parse_unary():
        nonlocal pos
        if peek() == '-':
            advance()
            return -parse_unary()
        if peek() == '+':
            advance()
            return parse_unary()
        return parse_atom()

    def parse_atom():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        if t == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            advance()
            return val
        if re.fullmatch(r'\d+\.\d+|\d+\.|\.\d+|\d+', t):
            advance()
            return float(t)
        raise ValueError(f"unexpected token: {t}")

    if not tokens:
        raise ValueError("empty expression")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("malformed expression: trailing tokens")
    return float(result)
